create or replace function public.protect_store_status() returns trigger language plpgsql security definer set search_path = public as $$ begin if auth.uid() is null or public.has_role(auth.uid(),'admin') then return new; end if; if tg_op = 'INSERT' then new.status := 'pending'; elsif new.status is distinct from old.status then new.status := old.status; end if; return new; end $$;
create or replace function public.update_order_status(_order uuid, _status text) returns void language plpgsql security definer set search_path = public as $$ declare _o public.orders; begin select * into _o from public.orders where id = _order for update; if _o.id is null then raise exception 'Order not found'; end if; if not (public.owns_store(_o.store_id) or public.has_role(auth.uid(),'admin')) then raise exception 'Not allowed'; end if; if not ((_o.status = 'pending_payment' and _status = 'cancelled') or (_o.status = 'paid' and _status in ('processing','cancelled')) or (_o.status = 'processing' and _status in ('shipped','cancelled')) or (_o.status = 'shipped' and _status = 'completed')) then raise exception 'Invalid order transition'; end if; if _status = 'cancelled' then update public.product_variants v set stock = v.stock + i.quantity from public.order_items i where i.order_id = _order and v.id = i.variant_id; end if; update public.orders set status = _status where id = _order; end $$;
create or replace function public.check_checkout_stock() returns trigger language plpgsql set search_path = public as $$ begin if new.stock < 0 then raise exception 'Not enough stock'; end if; return new; end $$;
create trigger guard_checkout_stock before update on public.product_variants for each row execute function public.check_checkout_stock();